static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / (1000 * 60 * 60 * 24 * 365);
    long month = (timeBucket % (1000 * 60 * 60 * 24 * 365)) / (1000 * 60 * 60 * 24 * 30);
    long day = (timeBucket % (1000 * 60 * 60 * 24 * 30)) / (1000 * 60 * 60 * 24);
    long hour = (timeBucket % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60);
    long minute = (timeBucket % (1000 * 60 * 60)) / (1000 * 60);
    long second = (timeBucket % (1000 * 60)) / 1000;

    if (dayStep == 1) {
        return year * 1000 * 60 * 60 * 24 + month * 1000 * 60 * 60 * 30 + day * 1000 * 60 * 60;
    } else if (dayStep == 11) {
        return year * 1000 * 60 * 60 * 24 + month * 1000 * 60 * 60 * 30 + day * 1000 * 60 * 60 + hour * 1000 * 60 + minute * 1000 + second;
    } else {
        return timeBucket;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        int c = str.charAt(i);
        if (c < 0x80) {
            size++;
        } else if (c < 0xC0) {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        } else if (c < 0xE0) {
            size += 2;
        } else if (c < 0xF0) {
            size += 3;
        } else if (c < 0xF8) {
            size += 4;
        } else if (c < 0xFC) {
            size += 5;
        } else if (c < 0xFE) {
            size += 6;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return size;
}

